class Main {
    public static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int i = 2; i <= Math.sqrt(n); i++) {
            if (n % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        int[] numbers = {2, 3, 4, 17, 20, 29};

        for (int num : numbers) {
            if (isPrime(num)) {
                System.out.println(num + " 是素数");
            } else {
                System.out.println(num + " 不是素数");
            }
        }
    }
}
